import { useId } from 'react';
import { useForm } from '@tanstack/react-form';
import type { DeepKeys } from '@tanstack/react-form';

import { FieldRenderer } from '@/components/formedible/field-renderer';
import { Form as FormRoot } from '@/components/formedible/form';
import type { FormProps } from '@/components/formedible/form';
import { normalizeOptions } from '@/lib/formedible/normalize-options';
import type { FormedibleFormValues, UseFormedibleOptions } from '@/lib/formedible/types';
import { buildFieldValidators, buildFormValidators } from '@/lib/formedible/validation';
import { formatValidationError } from '@/lib/formedible/zod-errors';

export function useFormedible<TFormValues extends FormedibleFormValues = FormedibleFormValues>(config: UseFormedibleOptions<TFormValues>) {
  const formId = useId();
  const normalizedOptions = normalizeOptions(config);
  const fields = normalizedOptions.fields;
  const form = useForm({
    defaultValues: config.formOptions.defaultValues,
    validators: buildFormValidators(config.schema, config.crossFieldValidation),
    onSubmit: async ({ value }) => {
      await config.formOptions.onSubmit?.({ value });
    },
  });

  function Form({ className, ...props }: FormProps) {
    return (
      <FormRoot
        className={className}
        onSubmit={(event) => {
          event.preventDefault();
          event.stopPropagation();
          form.handleSubmit();
        }}
        {...props}
      >
        {fields.map((fieldConfig) => (
          <form.Field
            key={fieldConfig.name}
            name={fieldConfig.name as DeepKeys<TFormValues>}
            validators={buildFieldValidators<TFormValues, DeepKeys<TFormValues>>(fieldConfig, config.schema, config.crossFieldValidation, config.asyncValidation)}
          >
            {(field) => {
              const error = field.state.meta.errors.map(formatValidationError).find((message) => message !== undefined);
              type FieldValueUpdate = Parameters<typeof field.handleChange>[0];

              return (
                <FieldRenderer
                  fieldConfig={fieldConfig}
                  field={{
                    id: `${formId}-${fieldConfig.name}`,
                    name: fieldConfig.name,
                    value: field.state.value,
                    error,
                    onBlur: field.handleBlur,
                    onChange: (nextValue) => field.handleChange(nextValue as FieldValueUpdate),
                  }}
                />
              );
            }}
          </form.Field>
        ))}
      </FormRoot>
    );
  }

  return { Form, form };
}

import type { ComponentProps } from 'react';

import { cn } from '@/lib/utils';

export type FormProps = ComponentProps<'form'>;

export function Form({ className, ...props }: FormProps) {
  return <form className={cn(className)} {...props} />;
}

import { getFieldComponent } from '@/components/formedible/fields/field-registry';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';

export function FieldRenderer<TFormValues extends FormedibleFormValues>(props: FormedibleFieldRenderProps<TFormValues>) {
  const FieldComponent = getFieldComponent<TFormValues>(props.fieldConfig.type);

  return <FieldComponent fieldConfig={props.fieldConfig} field={props.field} />;
}

import type { ReactNode } from 'react';

import { Field, FieldDescription, FieldError, FieldLabel } from '@/components/ui/field';
import type { FormedibleFieldController, FormedibleFormValues, NormalizedFieldConfig } from '@/lib/formedible/types';

export interface FieldWrapperProps<TFormValues extends FormedibleFormValues = FormedibleFormValues> {
  readonly fieldConfig: NormalizedFieldConfig<TFormValues>;
  readonly field: FormedibleFieldController;
  readonly children: ReactNode;
}

export function FieldWrapper<TFormValues extends FormedibleFormValues>({ fieldConfig, field, children }: FieldWrapperProps<TFormValues>) {
  return (
    <Field
      className={fieldConfig.className}
      data-disabled={fieldConfig.disabled ? 'true' : undefined}
      data-invalid={field.error ? 'true' : undefined}
    >
      {fieldConfig.label ? (
        <FieldLabel htmlFor={field.id}>
          {fieldConfig.label}
          {fieldConfig.required ? <span aria-hidden="true"> *</span> : undefined}
        </FieldLabel>
      ) : undefined}
      {children}
      {fieldConfig.description ? <FieldDescription>{fieldConfig.description}</FieldDescription> : undefined}
      {field.error ? <FieldError>{field.error}</FieldError> : undefined}
    </Field>
  );
}

import { Input as TextInput } from '@/components/ui/input';
import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';

const textInputTypes = ['email', 'password', 'url', 'tel'] as const;

function getInputType(type: string) {
  return textInputTypes.some((inputType) => inputType === type) ? type : 'text';
}

export function TextField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const value = typeof field.value === 'string' ? field.value : '';

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <TextInput
        id={field.id}
        name={field.name}
        type={getInputType(fieldConfig.type)}
        value={value}
        placeholder={fieldConfig.placeholder}
        disabled={fieldConfig.disabled}
        required={fieldConfig.required}
        aria-invalid={field.error ? true : undefined}
        className={fieldConfig.inputClassName}
        onBlur={field.onBlur}
        onChange={(event) => field.onChange(event.target.value)}
      />
    </FieldWrapper>
  );
}

